INSERT INTO assets (id, owner_id, title, slug, description, category, license_type, pricing_type, price, currency, territory, allowed_uses, restrictions, status, view_count, request_count, published_at, created_at, updated_at) VALUES
(gen_random_uuid(), 'aa000000-0000-0000-0000-digitalaxios1', 'Da Vinci Inventa - Plataforma White-Label', 'da-vinci-inventa-plataforma-white-label', 'Licencia completa de la plataforma Da Vinci Inventa para operar tu propio marketplace de activos intelectuales. Incluye frontend Next.js 15, backend NestJS microservicios, base de datos PostgreSQL, gateway API, sistema de autenticacion OAuth, mensajeria y panel de administracion. Soporte tecnico incluido.', 'software', 'exclusive', 'negotiable', 25000.00, 'USD', 'Mundial', ARRAY['operar marketplace propio','personalizar marca y dominio','agregar categorias y verticales'], ARRAY['no competir directamente con Da Vinci Inventa en Argentina'], 'published', 1580, 42, NOW(), NOW(), NOW()),
(gen_random_uuid(), 'aa000000-0000-0000-0000-digitalaxios1', 'Kit de Lanzamiento para Startups - Digital Axios', 'kit-lanzamiento-startups-digital-axios', 'Todo lo que necesita una startup para lanzar en 30 dias: arquitectura de sistema validada, stack tecnologico preconfigurado, CI/CD pipeline, infraestructura en la nube, documentacion tecnica y sesiones de consultoria. Probado en 15+ productos lanzados.', 'software', 'non_exclusive', 'fixed', 8500.00, 'USD', 'Latinoamerica', ARRAY['uso en proyecto propio','personalizar y adaptar'], ARRAY['no redistribuir como producto independiente'], 'published', 923, 31, NOW(), NOW(), NOW()),
(gen_random_uuid(), 'aa000000-0000-0000-0000-digitalaxios1', 'Metodologia de Producto Digital - Digital Axios', 'metodologia-producto-digital-digital-axios', 'Framework propietario de 16 semanas para llevar una idea a producto digital validado: discovery, definicion de MVP, sprints de desarrollo, lanzamiento y metricas. Incluye plantillas Notion, workshops facilitados y acompanamiento del equipo Digital Axios.', 'business_model', 'non_exclusive', 'fixed', 4200.00, 'USD', 'Argentina', ARRAY['uso en equipo propio','adaptacion al rubro'], ARRAY['creditar a Digital Axios como fuente'], 'published', 756, 24, NOW(), NOW(), NOW()),
(gen_random_uuid(), 'aa000000-0000-0000-0000-digitalaxios1', 'Sistema de Diseno Da Vinci - Design System Completo', 'sistema-diseno-da-vinci-design-system', 'El design system detras de Da Vinci Inventa: tokens de color, tipografia, componentes React + Tailwind, dark mode nativo, iconografia y guias de UX writing en espanol. Mas de 80 componentes listos para produccion. Figma + codigo incluido.', 'design', 'non_exclusive', 'fixed', 3800.00, 'USD', 'Mundial', ARRAY['uso en productos propios','modificacion libre','proyectos comerciales'], ARRAY['no redistribuir como design system standalone'], 'published', 1102, 38, NOW(), NOW(), NOW());
